const tickerItems = rawItems
  .filter((item) => item && typeof item.title === 'string' && item.title.trim())
  .slice(0, 3)
  .map((item) => {
    const href = resolveUrl(item.url) || resolveUrl(item.fileUrl);
    const fileUrl = resolveUrl(item.fileUrl);
    const rawTitle = item.title!.trim();
    const truncatedTitle = rawTitle.length > 70 ? `${rawTitle.slice(0, 67)}…` : rawTitle;
    const isTenderLike = item.sourceType === 'tender' || item.sourceType === 'corrigendum';
    const deadline = formatDeadline(item.closingDate);
    return {
      ...item,
      title: truncatedTitle,
      fullTitle: rawTitle,
      href,
      meta: documentMeta(item),
      prefix: prefixFor(item.sourceType),
      prefixClass: prefixClasses(item.sourceType),
      newTab: isDocumentLink(href, fileUrl),
      isUrgent: (item.priority || 'Normal') === 'Urgent',
      isNew: item.isNew === true,
      isClosingSoon: item.closingSoon === true,
      referenceLabel: isTenderLike && item.referenceNo ? item.referenceNo : '',
      deadlineLabel: deadline
        ? isTenderLike
          ? `Closes ${deadline}`
          : `Valid till ${deadline}`
        : '',
